/**
 * @method
 * @name scwin.fnDownload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnDownload = async function () {
    /* sdd-asis-lifecycle:begin fnDownload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (!$c.date.isDate($c.util.getComponent('cal_fromDate').getValue())) {
        await $c.win.alert("시작일자 형식이 틀립니다");
        return;
    }
    if (!scwin.fCheckDateYear($c.util.getComponent('cal_fromDate').getValue())) {
        $c.util.getComponent('cal_fromDate').setValue('2012-01-01');
        await $c.win.alert("2012년 데이터부터 다운로드 가능합니다");
        return;
    }
    if (!$c.date.isDate($c.util.getComponent('cal_toDate').getValue())) {
        await $c.win.alert("종료일자 형식이 틀립니다");
        return;
    }
    if (scwin.checkDateValidation($c.util.getComponent('cal_fromDate'), $c.util.getComponent('cal_toDate')) === false) {
        return;
    }
    if ($c.date.addYear($c.util.getComponent('cal_fromDate').getValue(), 3) < $c.date.addYear($c.util.getComponent('cal_toDate').getValue(), 0)) {
        await $c.win.alert("조회기간은 3년 이내만 가능합니다.");
        return;
    }
    const srchgubun = ($c.util.getComponent("dma_fnDownloadReq").get("searchGubun") || '');
    if (srchgubun === "decl") {
        $c.util.getComponent("dma_fnDownloadReq").set("method", "downloadDecl");
    } else {
        if (srchgubun === "appl") {
            $c.util.getComponent("dma_fnDownloadReq").set("method", "downloadAppl");
        } else {
            if (srchgubun === "trd") {
                $c.util.getComponent("dma_fnDownloadReq").set("method", "downloadTrd");
            } else {
                if (srchgubun === "trddetail") {
                    $c.util.getComponent("dma_fnDownloadReq").set("method", "downloadTrdDetail");
                }
            }
        }
    }
    $("#searchForm").attr('onsubmit', '');
    $c.util.getComponent("dma_fnDownloadReq").set("currentPageSize", "3000");
    $c.util.getComponent("dma_fnDownloadReq").set("pageIndex", "1");
    await scwin.tx_fnDownload();
    $("#searchForm").attr('onsubmit', 'return false;');
    /* sdd-asis-lifecycle:end */
};


